<template><el-card class="missing-panel"><template #header><div class="head"><strong>{{ t('publicModelsAdmin.missingTitle') }}</strong><el-button :loading="loading" @click="emit('sync')">{{ t('publicModelsAdmin.sync') }}</el-button></div></template>
  <el-alert v-if="error" role="alert" type="error" :closable="false" :title="t('publicModelsAdmin.loadFailed')"><p v-if="error.requestId">{{ t('publicModelsAdmin.requestId') }}: <code>{{ error.requestId }}</code></p></el-alert>
  <el-skeleton v-else-if="loading && !missing" :rows="3" animated />
  <template v-else><section><h3>{{ t('publicModelsAdmin.observedWithoutConfiguration') }}</h3><el-empty v-if="!observedWithoutConfiguration.length" :description="t('publicModelsAdmin.none')" :image-size="48" /><ul v-else><li v-for="id in observedWithoutConfiguration" :key="id"><code>{{ id }}</code><el-button link type="primary" @click="emit('create', id)">{{ t('publicModelsAdmin.create') }}</el-button></li></ul></section>
  <section><h3>{{ t('publicModelsAdmin.configuredMissingUpstream') }}</h3><el-empty v-if="!configuredMissingUpstream.length" :description="t('publicModelsAdmin.none')" :image-size="48" /><ul v-else><li v-for="item in configuredMissingUpstream" :key="item.guid"><router-link :to="`/admin/public-models/${item.guid}`">{{ item.displayName }}</router-link><code>{{ item.upstreamModelId }}</code></li></ul></section></template>
</el-card></template>
<script setup>import { computed } from 'vue';import { useI18n } from '@/composables/useI18n';const props=defineProps({missing:{type:Object,default:null},loading:Boolean,error:{type:Object,default:null}});const emit=defineEmits(['sync','create']);const {t}=useI18n();const observedWithoutConfiguration=computed(()=>props.missing?.observedWithoutConfiguration??[]);const configuredMissingUpstream=computed(()=>props.missing?.configuredMissingUpstream??[])</script>
<style scoped>.head,li{display:flex;align-items:center;justify-content:space-between;gap:12px}section+section{margin-top:20px}ul{padding:0;list-style:none}li{padding:8px 0;border-bottom:1px solid var(--border)}code{font-family:ui-monospace,monospace;overflow-wrap:anywhere}@media(max-width:680px){li{align-items:flex-start;flex-direction:column}}</style>
